(()=>{let scheduled=false;function update(){scheduled=false;for(const node of document.querySelectorAll(".pad-focus"))if(node!==document.activeElement)node.classList.remove("pad-focus");for(const frame of document.querySelectorAll('iframe'))frame.classList.toggle('ob-frame-focused',document.activeElement===frame)}function schedule(){if(!scheduled){scheduled=true;setTimeout(update,0)}}for(const event of ['focus','blur','focusin','focusout','keyup','pointerup'])window.addEventListener(event,schedule,true);schedule()})();
